const lens = document.getElementById('ai4a11y-magnifier');
const intro = document.getElementById('intro-p');
if (!intro) return false;
if (!lens) return true;

const iRect = intro.getBoundingClientRect();
document.dispatchEvent(new MouseEvent('mousemove', {
  bubbles: true,
  clientX: Math.round(iRect.left + 20),
  clientY: Math.round(iRect.top + 8)
}));
await new Promise(r => requestAnimationFrame(() => setTimeout(r, 60)));
if (window.getComputedStyle(lens).display !== 'block') return false;

document.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, key: 'Escape' }));
const dismissed = window.getComputedStyle(lens).display === 'none';
document.dispatchEvent(new MouseEvent('mouseleave'));
